export default '/**\n * Stackra file contract:\n * Purpose: the "invalid" demo of the native TreeSelect: a required department left empty, with its error under the field until one is chosen.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decision 3); ADR 0060;\n *          STA-1371 (wave C, owner request 2026-10-29).\n */\nimport { TreeSelect, useCatalogueText } from "@stackra/ui/native";\nimport { useState } from "react";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { TREE_SELECT_DEMO_KEYS } from "#src/demos/free/tree-select/tree-select-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = TREE_SELECT_DEMO_KEYS.demo_free.tree_select.invalid;\n\n/** TreeSelect: required and empty. */\nexport default function Invalid() {\n  const t = useCatalogueText(MESSAGES.en);\n  const [department, setDepartment] = useState<readonly string[]>([]);\n  return (\n    <TreeSelect\n      label={t(K.label)}\n      isRequired\n      isInvalid={department.length === 0}\n      errorMessage={t(K.error)}\n      value={department}\n      onChange={setDepartment}\n      defaultExpandedKeys={["finance"]}\n      items={[\n        {\n          id: "finance",\n          label: t(K.finance),\n          children: [\n            { id: "payroll", label: t(K.payroll) },\n            { id: "accounts", label: t(K.accounts) },\n          ],\n        },\n        { id: "sales", label: t(K.sales) },\n      ]}\n    />\n  );\n}\n';
